class LandingScreen extends StatelessWidget {
  const LandingScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.of(context).size.width;
    final isDesktop = width > 850;

    return Scaffold(
      backgroundColor: brandNavy,
      body: SingleChildScrollView(
        child: Column(
          children: [
            const Navbar(),
            const HeroSection(),
            const MerchantSpotlightSection(),
            const ProductShowcaseSection(),
            const BusinessSection(),
            const VoiceReminderSection(),
            const DeveloperSection(),
            const TrustSection(),
            const CTASection(),
            const Footer(),
          ],
        ),
      ),
    );
  }
}

// ============================================================
// NAVBAR
// ============================================================
class Navbar extends StatelessWidget {
  const Navbar({super.key});

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final mobile = constraints.maxWidth < 850;

        return Container(
          padding: EdgeInsets.symmetric(
            horizontal: mobile ? 24 : 70,
            vertical: 20,
          ),
          color: brandNavy,
          child: Row(
            children: [
              Row(
                children: [
                  const NautikLogoMark(size: 34),
                  const SizedBox(width: 10),
                  const Text(
                    'ElumoPay',
                    style: TextStyle(
                      fontSize: 22,
                      fontWeight: FontWeight.w900,
                      color: brandText,
                      letterSpacing: -0.8,
                    ),
                  ),
                ],
              ),
              const Spacer(),
              if (!mobile) ...[
                _navItem('Products'),
                _navItem('AI Intelligence'),
                _navItem('Developers'),
                _navItem('Company'),
                const SizedBox(width: 25),
              ],
              TextButton(
                onPressed: () {
                  Navigator.pushNamed(context, '/login');
                },
                child: const Text('Log in', style: TextStyle(color: brandCyan, fontWeight: FontWeight.w800)),
              ),
              const SizedBox(width: 10),
              FilledButton(
                onPressed: () {
                  Navigator.pushNamed(context, '/login');
                },
                style: FilledButton.styleFrom(
                  backgroundColor: brandGreen,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 22,
                    vertical: 14,
                  ),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                ),
                child: const Text('Get started', style: TextStyle(fontWeight: FontWeight.bold)),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _navItem(String title) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 15),
      child: Text(
        title,
        style: const TextStyle(
          color: brandMuted,
          fontWeight: FontWeight.w600,
        ),
      ),
    );
  }
}

